//! The built-in catalog for `asimeow recommend`: project markers and the folders they
//! generate, each with a confidence. The data lives in `catalog.yaml`, compiled in.

use crate::config::Rule;
use serde::Deserialize;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Confidence {
    /// Generated by a tool, never source.
    High,
    /// A generic name (`build`, `dist`, `vendor`) that is sometimes real source.
    Check,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogRule {
    pub name: String,
    pub file_match: String,
    pub exclusions: Vec<CatalogExclusion>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogExclusion {
    pub name: String,
    pub confidence: Confidence,
}

impl CatalogRule {
    /// As a plain config rule, for the matcher.
    pub fn to_rule(&self) -> Rule {
        Rule {
            name: self.name.clone(),
            file_match: self.file_match.clone(),
            exclusions: self.exclusions.iter().map(|e| e.name.clone()).collect(),
        }
    }

    pub fn confidence_of(&self, folder: &str) -> Option<Confidence> {
        self.exclusions
            .iter()
            .find(|e| e.name == folder)
            .map(|e| e.confidence)
    }
}

/// The built-in catalog.
pub fn catalog() -> Vec<CatalogRule> {
    serde_yaml::from_str(include_str!("catalog.yaml")).expect("built-in catalog.yaml is valid")
}
